  PRIMARY KEY (`id`) NOT ENFORCED
) WITH (
  'format-version' = '2',
  'write.upsert.enabled' = 'true',
  'write.parquet.compression-codec' = 'zstd'
);

-- vouchers
CREATE TEMPORARY TABLE `src_vouchers` (
  `id` STRING,
  `code` STRING,
  `scope` STRING,
  `shop_id` STRING,
  `kind` STRING,
  `value` BIGINT,
  `max_discount` BIGINT,
  `min_spend` BIGINT,
  `usage_limit` INT,
  `per_customer_limit` INT,
  `starts_at` TIMESTAMP_LTZ(6),
  `ends_at` TIMESTAMP_LTZ(6),
  `created_at` TIMESTAMP_LTZ(6),
  `updated_at` TIMESTAMP_LTZ(6),
  `_source_ts` TIMESTAMP_LTZ(3) METADATA FROM 'value.source.timestamp' VIRTUAL
) WITH (
  'connector' = 'kafka',
  'topic' = 'cdc.ecommerce.vouchers',
  'properties.bootstrap.servers' = 'kafka:9092',
  'properties.group.id' = 'flink-silver',
  'properties.auto.offset.reset' = 'earliest',
  'scan.startup.mode' = 'group-offsets',
  'format' = 'debezium-json',
  'debezium-json.timestamp-format.standard' = 'ISO-8601'
);
CREATE TABLE IF NOT EXISTS lakehouse.silver.`vouchers` (
  `id` STRING NOT NULL,
  `code` STRING,
  `scope` STRING,
  `shop_id` STRING,
  `kind` STRING,
  `value` BIGINT,
  `max_discount` BIGINT,
  `min_spend` BIGINT,
  `usage_limit` INT,
  `per_customer_limit` INT,
  `starts_at` TIMESTAMP_LTZ(6),
  `ends_at` TIMESTAMP_LTZ(6),
  `created_at` TIMESTAMP_LTZ(6),
  `updated_at` TIMESTAMP_LTZ(6),
  `_source_ts` TIMESTAMP_LTZ(3),
  PRIMARY KEY (`id`) NOT ENFORCED
) WITH (
  'format-version' = '2',
  'write.upsert.enabled' = 'true',
  'write.parquet.compression-codec' = 'zstd'
);

